def on_complete(outcome):                # delivered exactly once, marshalled
    if outcome.cancelled:
        return                           # requested stop, not a failure
    if outcome.error:
        report(outcome.error)            # failure path of the same event
    else:
        consume(outcome.result, outcome.user_state)   # which call finished
